<?php /** @var \Sysfera\Plugin $sf @var \SysferaStoragerent\Ctx $ctx @var string $lang @var array $rows @var string $q @var string $status @var bool $canWrite @var bool $finance @var array $statuses */
require __DIR__ . '/_nav.php'; ?>
<form class="sr-filter" method="get" action="<?= e($sf->url('/tenants')) ?>"><input type="search" name="q" value="<?= e($q) ?>" placeholder="<?= e($sf->t('search_ph')) ?>">
  <select name="status"><option value=""><?= e($sf->t('all_statuses')) ?></option><?php foreach ($statuses as $s): ?><option value="<?= e($s) ?>"<?= $s === $status ? ' selected' : '' ?>><?= e($sf->t('st_' . $s)) ?></option><?php endforeach; ?></select>
  <button class="btn"><?= e($sf->t('search')) ?></button><?php if ($canWrite): ?><a class="btn primary" href="<?= e($sf->url('/tenant/0')) ?>">+ <?= e($sf->t('tenant_add')) ?></a><?php endif; ?></form>
<?php if (!$rows): ?><div class="card empty"><?= e($sf->t('none')) ?></div><?php else: ?>
<div class="card sr-scroll"><table><thead><tr><th><?= e($sf->t('f_name')) ?></th><th><?= e($sf->t('f_tin')) ?></th><th><?= e($sf->t('f_contact')) ?></th><th><?= e($sf->t('f_phone')) ?></th><th><?= e($sf->t('f_restrictions')) ?></th><th><?= e($sf->t('col_status')) ?></th><?php if ($finance): ?><th><?= e($sf->t('col_debt')) ?></th><?php endif; ?></tr></thead><tbody>
<?php foreach ($rows as $t): ?><tr><td><a href="<?= e($sf->url('/tenant/' . $t['id'])) ?>"><b><?= e($t['name']) ?></b></a><br><small class="muted"><?= e($sf->t('kind_' . $t['kind'])) ?></small></td><td><?= e($t['tin']) ?></td><td><?= e($t['contact']) ?><br><small class="muted"><?= e($t['email']) ?></small></td><td><?= e($t['phone']) ?></td>
  <td><?php if ($t['restrictions'] !== ''): ?><span class="badge warn" title="<?= e($t['restrictions']) ?>"><?= e($sf->t('restriction')) ?></span> <small><?= e(function_exists('mb_strimwidth') ? mb_strimwidth((string)$t['restrictions'], 0, 60, '…') : substr((string)$t['restrictions'], 0, 60)) ?></small><?php endif; ?></td>
  <td><span class="badge <?= e(sr_cls($t['status'])) ?>"><?= e($sf->t('st_' . $t['status'])) ?></span></td><?php if ($finance): ?><td class="<?= $t['debt'] > 0 ? 'bad-t' : '' ?>"><?= e(sr_m($t['debt'], $lang)) ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
